  remove(id: string) {
    if (!this.ids.delete(id)) return false;
    for (const [tick, bucket] of this.buckets) {
      const remaining = bucket.filter((item) => item.id !== id);
      if (remaining.length) this.buckets.set(tick, remaining);
      else this.buckets.delete(tick);
    }
    return true;
  }
